class Solution {
public:
    long long waysToBuyPensPencils(int total, int cost1, int cost2) {
        long long ans = 0;
        int maxPens = total / cost1;
        for (int pens = 0; pens <= maxPens; pens++) {
            long long rem = total - (long long)pens * cost1;
            ans += rem / cost2 + 1;
        }
        return ans;
    }
};

class Solution {
    public long waysToBuyPensPencils(int total, int cost1, int cost2) {
        long ans = 0;
        int maxPens = total / cost1;
        for (int pens = 0; pens <= maxPens; pens++) {
            long rem = total - (long) pens * cost1;
            ans += rem / cost2 + 1;
        }
        return ans;
    }
}

/**
 * @param {number} total
 * @param {number} cost1
 * @param {number} cost2
 * @return {number}
 */
var waysToBuyPensPencils = function(total, cost1, cost2) {
    let ans = 0;
    const maxPens = Math.floor(total / cost1);
    for (let pens = 0; pens <= maxPens; pens++) {
        const rem = total - pens * cost1;
        ans += Math.floor(rem / cost2) + 1;
    }
    return ans;
};
